pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        // Ensure caller is not the current owner
        vm.assume(caller != address(this));
        vm.assume(caller != c.owner());
        // Ensure newOwner is not the current owner to observe a clear change
        vm.assume(newOwner != c.owner());

        // Record the owner before the call
        address ownerBefore = c.owner();

        // Non-owner caller attempts to transfer ownership
        vm.prank(caller);
        bool ok = true;
        try c.transferOwnership(newOwner) { ok = true; } catch { ok = false; }

        // The rule: after a call that does not revert, the owner must remain unchanged
        if (ok) {
            assertTrue(c.owner() == ownerBefore);
        }
    }
}

