pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address currentOwner, address newOwner) public {
        // ensure owner and newOwner are distinct so the bug can be triggered
        vm.assume(currentOwner != newOwner);

        // set the initial owner to the fuzzed currentOwner
        vm.prank(c.owner());
        c.transferOwnership(currentOwner);

        // currentOwner calls transferOwnership to delegate ownership to newOwner
        vm.prank(currentOwner);
        c.transferOwnership(newOwner);

        // the universal rule: after a successful ownership transfer,
        // the contract's owner must be the intended newOwner
        assertTrue(c.owner() == newOwner);
    }
}

